import{d as g,C as n,o as d,c as p,E as i,a3 as o}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"萃卦","description":"第四十五卦·泽地萃——泽上于地，万物荟萃；人心聚拢，聚以正也。","frontmatter":{"title":"萃卦","description":"第四十五卦·泽地萃——泽上于地，万物荟萃；人心聚拢，聚以正也。","category":"hexagram","aliases":["萃","泽地萃"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-45.md","filePath":"yijing/hexagrams/hexagram-45.md","lastUpdated":1787800334000}'),h={name:"yijing/hexagrams/hexagram-45.md"},x=g({...h,setup(m){const a=[{id:"cui",term:"萃",pinyin:"cuì",meaning:"聚拢、聚集；草木丛生之貌。",context:"全卦主题：人心的聚拢、力量的聚拢、方向的聚拢。"},{id:"fu",term:"孚"},{id:"buzhong",term:"不终",pinyin:"bù zhōng",meaning:"不能坚持到底。"},{id:"luan",term:"乱",pinyin:"luàn",meaning:"混乱、紊乱。「乃乱乃萃」：又乱、又渴求相聚。"},{id:"hao",term:"号",pinyin:"háo",meaning:"呼号、呼喊。"},{id:"yiwuo",term:"一握",pinyin:"yī wò",meaning:"一握手之间、一转念的工夫。",context:"「一握为笑」：呼号之后，转悲为笑。"},{id:"xu",term:"恤"},{id:"jiu",term:"咎"},{id:"yin",term:"引",pinyin:"yǐn",meaning:"牵引、引导。",context:"「引吉」：受九五牵引而聚，吉。"},{id:"yue",term:"禴",pinyin:"yuè",meaning:"薄祭、夏祭；祭品薄而诚意足。",context:"「孚乃利用禴」：真心胜过形式。"},{id:"jie",term:"嗟",pinyin:"jiē",meaning:"叹息、感叹。"},{id:"lin",term:"吝"},{id:"wei",term:"位",pinyin:"wèi",meaning:"地位、位置。",context:"「萃有位」：聚拢众人而居尊位。"},{id:"yuanyongzhen",term:"元永贞",pinyin:"yuán yǒng zhēn",meaning:"元（根本）、永（长久）、贞（守正）。",context:"换人心，只有这一条路。"},{id:"huiwang",term:"悔亡"},{id:"jizi",term:"赍咨",pinyin:"jī zī",meaning:"叹息、嗟叹之声。"},{id:"tiyi",term:"涕洟",pinyin:"tì yí",meaning:"流泪、流涕；痛哭的样子。"},{id:"wangjiamiao",term:"王假有庙",pinyin:"wáng gé yǒu miào",meaning:"君王亲至宗庙。「假」通「格」，至、到。",context:"以最高的诚意，把人心聚于一处。"},{id:"daxing",term:"用大牲",pinyin:"yòng dà shēng",meaning:"用牛等大牲口祭祀；以厚礼郑重致敬。"}],r=[{position:"初六",type:"yin",text:"有孚不终，乃乱乃萃。若号，一握为笑，勿恤，往无咎。",xiang:"乃乱乃萃，其志乱也。",textModern:"诚信没能坚持到底，于是又混乱、又渴求相聚；仿佛呼号求助，一握手之间转悲为笑。不必忧虑，前往没有灾祸。",xiangModern:"又乱又聚，是因为心志混乱不定。"},{position:"六二",type:"yin",text:"引吉，无咎。孚乃利用禴。",xiang:"引吉无咎，中未变也。",textModern:"受牵引而聚，吉祥，无灾祸；有诚信，用薄祭也足以通神。",xiangModern:"牵引得吉而无咎，是因为中正之心没有改变。"},{position:"六三",type:"yin",text:"萃如，嗟如，无攸利。往无咎，小吝。",xiang:"往无咎，上巽也。",textModern:"想聚聚不成，只能叹息，无所利；前往没有灾祸，但有小憾惜。",xiangModern:"前往无咎，是因为六三以柔顺上承九四之阳。"},{position:"九四",type:"yang",text:"大吉，无咎。",xiang:"大吉无咎，位不当也。",textModern:"大为吉祥，无灾祸。",xiangModern:"大吉而无咎，是因为九四阳居阴位、位不当，须大吉方可免咎。"},{position:"九五",type:"yang",text:"萃有位，无咎。匪孚，元永贞，悔亡。",xiang:"萃有位，志未光也。",textModern:"聚拢众人而居尊位，无灾祸；但还未赢得诚信，须以根本、长久、守正之心，悔恨才会消亡。",xiangModern:"聚而有位，但志向尚未光大。"},{position:"上六",type:"yin",text:"赍咨涕洟，无咎。",xiang:"赍咨涕洟，未安上也。",textModern:"叹息流泪、痛哭流涕，但没有灾祸。",xiangModern:"叹息流泪，是因为居于极上而心不得安。"}];return(u,t)=>{const e=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),s=n("DaoKeywordCards");return d(),p("div",null,[i(e,{name:"萃",fullName:"泽地萃",upper:"☱",lower:"☷",guaCi:"萃，亨。王假有庙。利见大人，亨，利贞。用大牲吉，利有攸往。",pinyin:["cuì"],element:"金",direction:"西",insight:"泽在地上，水聚成泽；万物荟萃、人心归聚，而聚拢的根本在于孚——诚信、真实、内外如一。",guaSlug:"45zedicui",lines:r}),t[0]||(t[0]=o('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>泽上于地，萃。君子以除戎器，戒不虞。</p><p>泽水高居地上，水聚而不泄，正是萃聚之象；君子由此领悟，聚拢之后要修整兵器、戒备意料之外的变故。</p><p>「除戎器」不是穷兵黩武——<strong>除</strong>是修治、整顿；<strong>戎器</strong>是兵器武备。除戎器，是把聚拢的力量收拾成随时可用的战斗力；<strong>戒不虞</strong>，是防备那些想不到的事。聚得越多，越要防得住。</p><p>分形结构：</p><ul><li>除戎器（修整武备）→ 微观：练好基本功，随时可战</li><li>戒不虞（戒备意外）→ 宏观：守住底线的风控，避免一聚即散</li></ul><p>聚是收获，防是护城河。只聚不防，是给散架埋下伏笔。队伍越大，越要有人看路口。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>萃，聚也。顺以说，刚中而应，故聚也。王假有庙，致孝享也。利见大人亨，聚以正也。用大牲吉，利有攸往，顺天命也。观其所聚，而天地万物之情可见矣。</p><p>逐句释义：</p><ul><li><strong>萃，聚也</strong> —— 萃，就是聚拢。全卦一个字：聚。</li><li><strong>顺以说，刚中而应，故聚也</strong> —— 下坤顺、上兑悦，九五刚健中正而上下相应，所以能聚。聚是有条件的：下面顺、上面悦、中间正。</li><li><strong>王假有庙，致孝享也</strong> —— 君王亲至宗庙，是以诚心致祭、以孝道凝聚人心。聚人心，先要从诚敬处聚起。</li><li><strong>利见大人亨，聚以正也</strong> —— 利于见大人而亨通，因为聚拢必须基于正道。聚的方式，决定聚的品质。</li><li><strong>用大牲吉，利有攸往，顺天命也</strong> —— 用大牲祭而吉、利于有所前往，是顺应天命大势，众人同心。</li><li><strong>观其所聚，而天地万物之情可见矣</strong> —— 看它聚拢的是什么，天地万物的情状就一目了然。你聚什么人、聚什么力、聚什么心，你就是什么样的人。</li></ul><blockquote><p><strong>聚以正哲学</strong>：聚拢的方式比聚拢的规模更重要。用什么把人心聚在一起，决定了这份聚合能走多远。沙漠里的队伍，方向一致才走得出去。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),i(l,{element:"金",guaSlug:"45zedicui",glossary:a,items:r}),t[1]||(t[1]=o('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初六-·-有孚不终-乃乱乃萃。若号-一握为笑-勿恤-往无咎" tabindex="-1">初六 · 有孚不终，乃乱乃萃。若号，一握为笑，勿恤，往无咎 <a class="header-anchor" href="#初六-·-有孚不终-乃乱乃萃。若号-一握为笑-勿恤-往无咎" aria-label="Permalink to &quot;初六 · 有孚不终，乃乱乃萃。若号，一握为笑，勿恤，往无咎&quot;">​</a></h3><ul><li><strong>有孚不终</strong> → 诚信没能坚持到底</li><li><strong>乃乱乃萃</strong> → 于是又混乱、又渴求相聚</li><li><strong>若号</strong> → 仿佛呼号求助</li><li><strong>一握为笑</strong> → 一握手之间，转悲为笑</li><li><strong>勿恤</strong> → 不必忧虑</li></ul><p>象曰「乃乱乃萃，其志乱也」——心志乱了。初六处在萃的开始，最缺定力：想聚，诚意却不稳，于是乱一阵、又聚一阵。</p><p><strong>沙漠意象</strong>：独自走在沙漠里，走得太久，信念开始动摇。一会儿怀疑方向（乱），一会儿又渴望遇到人群（萃）。此时不要硬扛——呼号求助，一握手之间，转悲为笑。</p><blockquote><p>核心洞见：乱不是错的信号，是要聚的信号。先乱后萃，是聚拢的必经前奏。</p></blockquote><h3 id="六二-·-引吉-无咎。孚乃利用禴" tabindex="-1">六二 · 引吉，无咎。孚乃利用禴 <a class="header-anchor" href="#六二-·-引吉-无咎。孚乃利用禴" aria-label="Permalink to &quot;六二 · 引吉，无咎。孚乃利用禴&quot;">​</a></h3><ul><li><strong>引吉</strong> → 受牵引而聚，吉</li><li><strong>孚乃利用禴</strong> → 有诚信，用薄祭也足以通神</li></ul><p>象曰「引吉无咎，中未变也」——中正之心没有改变。六二居中得正，不争不抢，静待九五牵引；别人用大牲重礼，六二只用薄祭（禴），因为真心胜过形式。</p><p><strong>沙漠意象</strong>：别人背着一袋袋干粮（形式），你只带一颗真心（孚）。在沙漠里，真心比干粮更能让人信你、跟你走。诚意，是聚拢真正的通货。</p><blockquote><p>核心洞见：孚乃利用禴——诚意足，形式薄也够；诚意虚，形式厚也是空。</p></blockquote><h3 id="六三-·-萃如-嗟如-无攸利。往无咎-小吝" tabindex="-1">六三 · 萃如，嗟如，无攸利。往无咎，小吝 <a class="header-anchor" href="#六三-·-萃如-嗟如-无攸利。往无咎-小吝" aria-label="Permalink to &quot;六三 · 萃如，嗟如，无攸利。往无咎，小吝&quot;">​</a></h3><ul><li><strong>萃如嗟如</strong> → 想聚聚不成，只能叹息</li><li><strong>无攸利</strong> → 无所利</li><li><strong>往无咎</strong> → 前往没有灾祸</li><li><strong>小吝</strong> → 但有小憾惜</li></ul><p>象曰「往无咎，上巽也」——六三上下皆阴、想聚无门，唯有上承九四之阳，以柔顺承刚，所以往而无咎。</p><p><strong>沙漠意象</strong>：明知道眼前是条苦路，叹着气，依旧走。不走才是大错，走了只是小憾。「往无咎」——无咎不是没有苦，是走过去了。</p><blockquote><p>核心洞见：知道是苦路还走，不是傻，是完整。无咎不是没有苦，是走过去了。</p></blockquote><h3 id="九四-·-大吉-无咎" tabindex="-1">九四 · 大吉，无咎 <a class="header-anchor" href="#九四-·-大吉-无咎" aria-label="Permalink to &quot;九四 · 大吉，无咎&quot;">​</a></h3><p>象曰「大吉无咎，位不当也」——九四阳居阴位，位不当；但它是卦中众阴唯一能亲近的阳爻，众人来聚。位不当，更要大吉：聚得来多少人，就得担得起多少责任。</p><p><strong>沙漠意象</strong>：走了很久，绿洲出现了——但绿洲只在「配得上了」的时候出现。不是绿洲来得晚，是你还没走到它该出现的地方。</p><blockquote><p>核心洞见：位不当，更要大吉。聚得来多少人，就得担得起多少责任。</p></blockquote><h3 id="九五-·-萃有位-无咎。匪孚-元永贞-悔亡" tabindex="-1">九五 · 萃有位，无咎。匪孚，元永贞，悔亡 <a class="header-anchor" href="#九五-·-萃有位-无咎。匪孚-元永贞-悔亡" aria-label="Permalink to &quot;九五 · 萃有位，无咎。匪孚，元永贞，悔亡&quot;">​</a></h3><ul><li><strong>萃有位</strong> → 聚拢众人、居于尊位</li><li><strong>匪孚</strong> → 还未赢得诚信（匪，非也）</li><li><strong>元永贞</strong> → 元（根本）、永（长久）、贞（守正）</li><li><strong>悔亡</strong> → 悔恨消亡</li></ul><p>象曰「萃有位，志未光也」——位置有了，志向还没光大。九五居君位，众人来聚，看似什么都有了——但「匪孚」：位置换不来人心。名分有了，信任还没有。怎么办？<strong>元永贞</strong>——回到根本、持续长久、守住正道，悔恨才会消亡。</p><p><strong>沙漠意象</strong>：你是队伍的领队，大家跟着你，但未必信你。位置是别人给的，人心得自己挣。</p><blockquote><p>核心洞见：匪孚不可怕，可怕的是以为「有位」就等于「有孚」。元永贞，才是把位置坐稳的唯一路径。</p></blockquote><h3 id="上六-·-赍咨涕洟-无咎" tabindex="-1">上六 · 赍咨涕洟，无咎 <a class="header-anchor" href="#上六-·-赍咨涕洟-无咎" aria-label="Permalink to &quot;上六 · 赍咨涕洟，无咎&quot;">​</a></h3><ul><li><strong>赍咨</strong> → 叹息</li><li><strong>涕洟</strong> → 流泪、流涕</li><li><strong>无咎</strong> → 没有灾祸</li></ul><p>象曰「赍咨涕洟，未安上也」——居于极上，心不得安。上六居卦之终，聚到尽头，众人各归其位，独自叹息流泪——但无咎，因为它把这场聚走完了。</p><p><strong>沙漠意象</strong>：终于走出沙漠，没有欢呼，反而哭了出来。这不是失败，是完整——眼泪把一路的苦都收尾了，哭过之后，人是干净的。</p><blockquote><p>核心洞见：走完了哭出来，是完整不是失败。赍咨涕洟而无咎，因为哭过之后，人是干净的。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',31)),i(s,{title:"字词释义",items:[{term:"萃",pinyin:["cuì"],meaning:"聚拢、聚集；草木丛生之貌。萃卦讲的是一切形式的聚拢：人心、力量、方向。"},{term:"孚"},{term:"王假有庙",pinyin:["wáng","gé","yǒu","miào"],meaning:"君王亲至宗庙。「假」通「格」，至、到；以最高诚意聚人心于一处。"},{term:"用大牲",pinyin:["yòng","dà","shēng"],meaning:"用牛等大牲口祭祀，以厚礼郑重致敬；喻聚拢时诚意要足。"},{term:"引吉",pinyin:["yǐn","jí"],meaning:"受牵引、带动而得吉。六二受九五牵引而聚。"},{term:"利用禴",pinyin:["lì","yòng","yuè"],meaning:"利于用薄祭。「禴」为夏祭、薄祭；真心胜过形式。"},{term:"萃如嗟如",pinyin:["cuì","rú","jiē","rú"],meaning:"想聚聚不成、只能叹息的样子。"},{term:"元永贞",pinyin:["yuán","yǒng","zhēn"],meaning:"元（根本）、永（长久）、贞（守正）；萃卦核心心法。"},{term:"赍咨涕洟",pinyin:["jī","zī","tì","yí"],meaning:"叹息流泪、痛哭流涕的样子；走完一路的收尾。"},{term:"除戎器",pinyin:["chú","róng","qì"],meaning:"修整兵器、整顿武备；聚众之后不忘戒备。"},{term:"戒不虞",pinyin:["jiè","bù","yú"],meaning:"戒备意料之外的变故。"},{term:"悔亡"},{term:"咎"},{term:"吝"},{term:"恤"},{term:"攸"}]}),t[2]||(t[2]=o('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>萃卦讲的是<strong>聚拢</strong>。上兑（泽、悦）覆于下坤（地、顺），泽水在地上聚成一片——人心的聚拢、力量的聚拢、方向的聚拢。卦辞「王假有庙」「用大牲吉」都在说同一件事：把众人聚到一处，用最高的诚意（孚）来凝住它。</p><p>全卦是一幅<strong>沙漠意象</strong>：一个人独自走在沙漠里，走向人群。一路有迷乱（初六）、有叹息（六三）、有绿洲（九四）、有眼泪（上六）——但每一步，都在往「聚」走去。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>聚拢的根本是<strong>孚</strong>——诚信、真实、内外如一。聚得再热闹，没有孚，终是一盘散沙。萃卦六爻全部指向这一点：</p><ul><li>初六乱而求聚，是聚的前奏</li><li>六二以诚相聚，真心胜过形式</li><li>六三叹而前行，无咎不是没苦</li><li>九四配得上才聚，绿洲自然出现</li><li>九五以元永贞换人心，位置换不来信任</li><li>上六走完即完整，哭出来是收尾</li></ul><blockquote><p>孚、无咎、元永贞——萃卦的三重心法：以孚聚人，以无咎渡难，以元永贞坐稳。</p></blockquote><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>先有孚：内外如一，才能聚人；名分（位）换不来信任</li><li>再辨向：乱是聚的前奏，不要怕乱；呼号求助，一握为笑</li><li>诚意优先：真心胜过形式（孚乃利用禴），别用排场撑场面</li><li>配得上才聚：能力没到位时，绿洲不会出现</li><li>聚而后防：除戎器、戒不虞，守住聚拢的成果</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>萃卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>王假有庙，用大牲吉</td><td>以最高诚意聚拢众人</td><td>聚以正</td></tr><tr><td>初六</td><td>有孚不终，乃乱乃萃，一握为笑</td><td>不怕乱，呼号求助，转悲为笑</td><td>乱是聚的前奏</td></tr><tr><td>六二</td><td>引吉，孚乃利用禴</td><td>受牵引而聚，真心胜过形式</td><td>诚意</td></tr><tr><td>六三</td><td>萃如，嗟如，无攸利，往无咎</td><td>知道是苦路，叹着气依旧走</td><td>无咎不是没苦</td></tr><tr><td>九四</td><td>大吉，无咎</td><td>配得上了，绿洲才出现</td><td>位不当更要大吉</td></tr><tr><td>九五</td><td>萃有位，匪孚，元永贞</td><td>位置换不来人心，元永贞才换得来</td><td>元永贞</td></tr><tr><td>上六</td><td>赍咨涕洟，无咎</td><td>走完了哭出来，是完整不是失败</td><td>完整</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>聚以正</strong>——用什么聚人心，决定能走多远</li><li><strong>孚是根</strong>——诚信、真实、内外如一</li><li><strong>乱是前奏</strong>——混乱是聚拢的前夜，不是失败的信号</li><li><strong>真心胜形式</strong>——孚乃利用禴，诚意足，薄祭也够</li><li><strong>配得上才聚</strong>——绿洲只在配得上的时候出现</li><li><strong>元永贞</strong>——根本、长久、守正，是换人心的唯一路径</li><li><strong>无咎哲学</strong>——不是没有苦，是走过去了</li><li><strong>走完即完整</strong>——赍咨涕洟而无咎，哭过之后人是干净的</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>萃卦于我最切身的体验，是「匪孚」。</p><p>昇哥曾任前端主管——坐的正是「萃有位」的位置：名分有了，团队也在，可时常感到「匪孚」：位置换不来人心。越是急着用「位」去收拢人，人心越散。后来明白，位置是别人给的，信任得自己挣——只有回到<strong>元永贞</strong>：回到根本（元）、持续长久（永）、守住正道（贞），人心才会慢慢回来。这也正是萃卦最狠的一课：聚拢的规模是表象，聚拢的质地（孚）才是里子。</p><p>六个爻像一条从散到聚、从聚到化的路：</p><ul><li><strong>初六</strong> → 混乱是聚拢的前奏，别怕乱</li><li><strong>六二</strong> → 诚意先行，真心胜过形式</li><li><strong>六三</strong> → 知道是苦路，叹着气依旧走</li><li><strong>九四</strong> → 配得上了，绿洲才出现</li><li><strong>九五</strong> → 位置换不来人心，元永贞才能</li><li><strong>上六</strong> → 走完了哭出来，是完整，不是失败</li></ul><p>明心立志，前路漫漫，还需风雨兼程。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：升（第四十六卦·地风升）、姤（第四十四卦·天风姤）</li><li>萃与升的连结：萃之后是升——人心聚拢了，力量就有了方向，自然向上生长。升卦卦辞「南征吉」：聚好之后，向着光明之地进发。</li><li>萃与姤的连结：姤是「遇」，萃是「聚」——先有不期而遇，后有刻意聚合。遇是种子，聚是把种子种成一整片林子。</li><li>相关专题：<a href="/Dao/topics/xiang-shu-li">象数理</a>、<a href="/Dao/topics/bian-yi">变易</a></li></ul>',23))])}}});export{y as __pageData,x as default};
